.ds-homepage { width: 100vw !important; max-width: 100vw !important; position: relative !important; left: 50% !important; right: 50% !important; margin-left: -50vw !important; margin-right: -50vw !important; box-sizing: border-box !important; overflow-x: hidden !important; font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif; color: #0f172a; background: #ffffff; }
.ds-homepage *, .ds-homepage *::before, .ds-homepage *::after { box-sizing: border-box; }
.entry-title, .entry-header, .post-title, .page-title, .wp-block-post-title, .site-header, #masthead, .site-branding, .header-footer-group, .theme-header, .custom-header, .nav-container { display: none !important; }

.ds-homepage {
  --ds-primary: #0066cc;
  --ds-primary-dark: #004c99;
  --ds-accent: #00a651;
  --ds-neutral: #f5f5f5;
  --ds-text: #0f172a;
  --ds-text-light: #475569;
  --ds-bg-alt: #f8fafc;
}

.ds-header { position: sticky; top: 0; z-index: 1000; background: rgba(255, 255, 255, 0.85); backdrop-filter: blur(12px) saturate(180%); -webkit-backdrop-filter: blur(12px) saturate(180%); border-bottom: 1px solid rgba(0, 0, 0, 0.06); box-shadow: 0 4px 30px rgba(0,0,0,0.03); transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1); padding: 1.25rem 0; }
.ds-header-inner { display: flex; justify-content: space-between; align-items: center; max-width: 1200px; margin: 0 auto; padding: 0 1.5rem; }
.ds-logo { font-size: 1.5rem; font-weight: 700; color: var(--ds-primary); text-decoration: none; letter-spacing: -0.03em; }

.ds-mobile-menu-toggle { display: none; }
.ds-mobile-menu-label { display: none; cursor: pointer; padding: 0.5rem; }
.ds-mobile-menu-label span { display: block; width: 24px; height: 2px; background: var(--ds-text); position: relative; transition: all 0.3s; }
.ds-mobile-menu-label span::before, .ds-mobile-menu-label span::after { content: ''; position: absolute; width: 24px; height: 2px; background: var(--ds-text); transition: all 0.3s; }
.ds-mobile-menu-label span::before { top: -8px; }
.ds-mobile-menu-label span::after { bottom: -8px; }

.ds-nav { display: flex; gap: 2rem; align-items: center; }
.ds-nav-link { position: relative; padding: 0.5rem 0; font-weight: 500; color: rgba(15, 23, 42, 0.8); text-decoration: none; transition: color 0.3s ease; }
.ds-nav-link::after { content: ""; position: absolute; bottom: 0; left: 0; width: 100%; height: 2px; background: var(--ds-primary); transform: scaleX(0); transform-origin: right; transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1); }
.ds-nav-link:hover { color: var(--ds-primary); }
.ds-nav-link:hover::after { transform: scaleX(1); transform-origin: left; }

.ds-btn { display: inline-flex; align-items: center; justify-content: center; padding: 0.875rem 1.75rem; border-radius: 8px; font-weight: 600; text-decoration: none; transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1); cursor: pointer; border: none; }
.ds-btn-primary { background: linear-gradient(135deg, var(--ds-primary), var(--ds-primary-dark)); color: #ffffff; box-shadow: 0 4px 12px rgba(0, 102, 204, 0.25); }
.ds-btn-primary:hover { transform: translateY(-2px); box-shadow: 0 8px 20px rgba(0, 102, 204, 0.35); color: #ffffff; }
.ds-btn-secondary { background: rgba(255,255,255,0.1); color: #ffffff; border: 1px solid rgba(255,255,255,0.3); backdrop-filter: blur(4px); }
.ds-btn-secondary:hover { background: rgba(255,255,255,0.2); transform: translateY(-2px); color: #ffffff; }

.ds-hero { position: relative; min-height: 75vh; display: flex; align-items: center; padding: clamp(4.5rem, 10vw, 8rem) 1.5rem; background: linear-gradient(rgba(15, 23, 42, 0.6), rgba(15, 23, 42, 0.8)), url('https://images.unsplash.com/photo-1598488035139-bdbb2231ce04?w=800&h=600') center/cover no-repeat; color: #ffffff; }
.ds-hero-content { max-width: 800px; margin: 0 auto; text-align: center; animation: dsFadeInUp 0.8s cubic-bezier(0.16, 1, 0.3, 1) both; }
.ds-hero h1 { font-size: clamp(2.5rem, 5vw, 4.5rem); font-weight: 800; line-height: 1.1; letter-spacing: -0.03em; margin-bottom: 1.5rem; margin-top: 0; }
.ds-hero p { font-size: clamp(1.125rem, 2vw, 1.5rem); font-weight: 400; opacity: 0.9; margin-bottom: 2.5rem; line-height: 1.5; }
.ds-hero-actions { display: flex; gap: 1rem; justify-content: center; flex-wrap: wrap; }

.ds-section { padding: clamp(4.5rem, 10vw, 8rem) 1.5rem; }
.ds-container { max-width: 1200px; margin: 0 auto; }
.ds-section-header { text-align: center; margin-bottom: 4rem; }
.ds-section-title { font-size: clamp(2rem, 4vw, 2.5rem); font-weight: 700; color: var(--ds-text); margin-bottom: 1rem; margin-top: 0; letter-spacing: -0.03em; }
.ds-section-subtitle { font-size: 1.125rem; color: var(--ds-text-light); max-width: 600px; margin: 0 auto; line-height: 1.6; }

.ds-intro { background: var(--ds-bg-alt); text-align: center; }
.ds-intro-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 2rem; margin-top: 3rem; }
.ds-stat { padding: 2.5rem 2rem; background: #ffffff; border-radius: 16px; box-shadow: 0 10px 30px rgba(0,0,0,0.03); transition: transform 0.3s ease; }
.ds-stat:hover { transform: translateY(-5px); }
.ds-stat h3 { font-size: 2.5rem; font-weight: 800; color: var(--ds-primary); margin: 0 0 0.5rem 0; letter-spacing: -0.03em; }
.ds-stat p { margin: 0; color: var(--ds-text-light); font-weight: 500; }

.ds-services-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 2rem; }
.ds-service-card { background: #ffffff; border-radius: 16px; overflow: hidden; border: 1px solid rgba(0,0,0,0.06); box-shadow: 0 10px 30px rgba(0,0,0,0.03); transition: all 0.3s ease; }
.ds-service-card:hover { transform: translateY(-5px); box-shadow: 0 20px 40px rgba(0,0,0,0.08); }
.ds-service-img-wrapper { overflow: hidden; height: 220px; }
.ds-service-img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.5s ease; }
.ds-service-card:hover .ds-service-img { transform: scale(1.05); }
.ds-service-content { padding: 2rem; }
.ds-service-title { font-size: 1.25rem; font-weight: 700; margin: 0 0 0.75rem 0; color: var(--ds-text); }
.ds-service-desc { color: var(--ds-text-light); line-height: 1.6; margin: 0; }

.ds-reviews { background: var(--ds-primary); color: #ffffff; }
.ds-reviews .ds-section-title { color: #ffffff; }
.ds-reviews .ds-section-subtitle { color: rgba(255,255,255,0.8); }
.ds-reviews-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 2rem; }
.ds-review-card { background: rgba(255,255,255,0.1); padding: 2.5rem 2rem; border-radius: 16px; backdrop-filter: blur(10px); border: 1px solid rgba(255,255,255,0.2); transition: transform 0.3s ease; }
.ds-review-card:hover { transform: translateY(-5px); }
.ds-stars { color: #fbbf24; font-size: 1.25rem; margin-bottom: 1rem; letter-spacing: 2px; }
.ds-review-text { font-size: 1.125rem; font-style: italic; margin: 0 0 1.5rem 0; line-height: 1.6; }
.ds-review-author { font-weight: 600; margin: 0; }
.ds-review-date { font-size: 0.875rem; font-weight: 400; opacity: 0.7; display: block; margin-top: 0.25rem; }

.ds-gallery-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 1.5rem; }
.ds-gallery-item { border-radius: 16px; overflow: hidden; height: 300px; box-shadow: 0 10px 30px rgba(0,0,0,0.03); }
.ds-gallery-item img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.5s ease; }
.ds-gallery-item:hover img { transform: scale(1.05); }

.ds-contact { background: var(--ds-bg-alt); }
.ds-contact-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 4rem; }
.ds-contact-info { display: flex; flex-direction: column; gap: 2rem; }
.ds-contact-item { display: flex; align-items: flex-start; gap: 1.25rem; }
.ds-contact-icon { width: 28px; height: 28px; color: var(--ds-primary); flex-shrink: 0; }
.ds-contact-details h4 { font-weight: 600; margin: 0 0 0.5rem 0; color: var(--ds-text); font-size: 1.125rem; }
.ds-contact-details p, .ds-contact-details a { color: var(--ds-text-light); text-decoration: none; line-height: 1.6; margin: 0; }
.ds-contact-details a:hover { color: var(--ds-primary); }
.ds-contact-cta { display: flex; align-items: center; justify-content: center; background: #ffffff; border-radius: 16px; padding: 3rem; box-shadow: 0 10px 30px rgba(0,0,0,0.03); text-align: center; border: 1px solid rgba(0,0,0,0.06); }
.ds-contact-cta h3 { font-size: 1.75rem; font-weight: 700; margin: 0 0 1rem 0; color: var(--ds-text); letter-spacing: -0.02em; }
.ds-contact-cta p { color: var(--ds-text-light); margin: 0 0 2rem 0; line-height: 1.6; }

.ds-footer { background: #0f172a; color: #94a3b8; padding: 4rem 1.5rem; text-align: center; }
.ds-footer p { margin: 0 0 0.5rem 0; }

@keyframes dsFadeInUp { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: translateY(0); } }
.ds-animate-1 { animation-delay: 0.1s; }
.ds-animate-2 { animation-delay: 0.2s; }
.ds-animate-3 { animation-delay: 0.3s; }

@media (max-width: 767px) {
  .ds-mobile-menu-label { display: block; }
  .ds-nav { display: none; }
  .ds-mobile-menu-toggle:checked ~ .ds-nav { display: flex; flex-direction: column; position: absolute; top: 100%; left: 0; width: 100%; background: #ffffff; padding: 1.5rem; box-shadow: 0 10px 15px rgba(0,0,0,0.05); border-top: 1px solid rgba(0,0,0,0.06); }
  .ds-nav-link { width: 100%; text-align: center; padding: 1rem 0; }
  .ds-header .ds-btn { display: none; }
  .ds-mobile-menu-toggle:checked ~ .ds-nav .ds-btn { display: inline-flex; width: 100%; margin-top: 1rem; }
}
@media (prefers-reduced-motion: reduce) { .ds-homepage * { transition: none !important; transform: none !important; animation: none !important; } }
